def point_in_triangle(p, a, b, c):
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    c1 = cross(a, b, p)
    c2 = cross(b, c, p)
    c3 = cross(c, a, p)

    # All cross products must have the same sign (or be zero)
    # Points on an edge have a cross product of zero
    return (c1 >= 0 and c2 >= 0 and c3 >= 0) or (c1 <= 0 and c2 <= 0 and c3 <= 0)

# The tests are satisfied even when p is exactly on an edge because any cross product
# including a point on a segment is zero, and the condition above accepts zero.
```

