def classify_triangle_by_sides(p1, p2, p3):
    d1 = (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2
    d2 = (p1[0] - p3[0])**2 + (p1[1] - p3[1])**2
    d3 = (p2[0] - p3[0])**2 + (p2[1] - p3[1])**2
    s = {d1, d2, d3}
    if len(s) == 1:
        return 'equilateral'
    elif len(s) == 2:
        return 'isosceles'
    else:
        return 'scalene'
```

