def flood_fill(grid, sr, sc, new_value):
    # Return a copy of the grid unchanged if the new value matches the starting cell's value
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
    original = grid[sr][sc]
    if original == new_value:
        return [row[:] for row in grid]

    # Perform flood fill on a copy of the grid
    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]
    to_visit = [(sr, sc)]
    while to_visit:
        r, c = to_visit.pop()
        if result[r][c] == original:
            result[r][c] = new_value
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    to_visit.append((nr, nc))
    return result
