def intersection_car_pass_count(events, green_duration):
    # North/south has green light for ticks 0, 1, ..., green_duration - 1
    # East/west has green light for ticks green_duration, ..., 2 * green_duration - 1
    # Then the cycle repeats
    # Starting with N/S at tick 0
    pass_count = 0
    for tick, direction in events:
        # Green phases: N/S is green at tick mod (2 * green_duration) < green_duration
        if tick % (2 * green_duration) < green_duration:
            if direction in ('N', 'S'):
                pass_count += 1
        else:
            if direction in ('E', 'W'):
                pass_count += 1
    return pass_count
```

